create schema if not exists ns_private;
revoke all on schema ns_private from public;
grant usage on schema ns_private to authenticated;
create table public.ns_memberships(household_id uuid not null references public.ns_households(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'adult' check(role='adult'),primary key(household_id,user_id));
create table public.ns_invites(id uuid primary key default gen_random_uuid(),household_id uuid not null references public.ns_households(id) on delete cascade,email text not null check(email=lower(trim(email)) and length(email) between 3 and 254),expires_at timestamptz not null default now()+interval '7 days',revoked boolean not null default false);
create index on public.ns_memberships(user_id);
create index on public.ns_invites(household_id);
create index on public.ns_invites(email);
alter table public.ns_memberships enable row level security;
alter table public.ns_invites enable row level security;
revoke all on public.ns_memberships,public.ns_invites from anon,authenticated;
grant select,insert,delete on public.ns_memberships to authenticated;
grant select,insert on public.ns_invites to authenticated;
grant update(revoked) on public.ns_invites to authenticated;
create function ns_private.owns_household(h uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from public.ns_households where id=h and owner_id=auth.uid()) $$;
create function ns_private.invited_email(e text) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null and lower(email)=e) $$;
revoke all on function ns_private.owns_household(uuid),ns_private.invited_email(text) from public,anon;
grant execute on function ns_private.owns_household(uuid),ns_private.invited_email(text) to authenticated;
create policy member_read on public.ns_memberships for select to authenticated using(user_id=(select auth.uid()) or ns_private.owns_household(household_id));
create policy member_join on public.ns_memberships for insert to authenticated with check(user_id=(select auth.uid()) and role='adult' and exists(select 1 from public.ns_invites i where i.household_id=ns_memberships.household_id and not i.revoked and i.expires_at>now() and ns_private.invited_email(i.email)));
create policy member_remove on public.ns_memberships for delete to authenticated using(user_id=(select auth.uid()) or ns_private.owns_household(household_id));
create policy invite_read on public.ns_invites for select to authenticated using(ns_private.owns_household(household_id) or (not revoked and expires_at>now() and ns_private.invited_email(email)));
create policy invite_create on public.ns_invites for insert to authenticated with check(ns_private.owns_household(household_id) and not revoked and expires_at>now() and expires_at<=now()+interval '7 days');
create policy invite_revoke on public.ns_invites for update to authenticated using(ns_private.owns_household(household_id)) with check(ns_private.owns_household(household_id) and revoked);
create policy household_member_read on public.ns_households for select to authenticated using(exists(select 1 from public.ns_memberships m where m.household_id=ns_households.id and m.user_id=(select auth.uid())));
